  runtimeConfiguration?: RuntimeConfiguration
}): void => {
  const { styles = [] } = runtimeConfiguration

  styles.forEach(({ href = '' }) => {
    if (!href) {
      return
    }

    const link = document.createElement('link')
    link.href = href
    link.type = 'text/css'
    link.rel = 'stylesheet'
    document.head.appendChild(link)
  })
}

